                "haeun.51hth.example",      // @ 누락
                "haeun.51@.example",        // 도메인 앞부분 누락
                "haeun.51@hth.",            // 최상위 도메인 누락
                "haeun 51@hth.example",     // 공백 포함 (중간 공백)
                "haeun.51@hth..example"     // 점(.) 연속 사용
