def is_valid_luhn(card_number: str) -> bool:
    # 1. 공백 및 하이픈(-) 제거
    sanitized = "".join(c for c in card_number if c.isdigit())

    if not sanitized or len(sanitized) < 2:
        return False

    total_sum = 0
    should_double = False

    # 2. 우측(마지막 자리)부터 좌측으로 순회
    for i in range(len(sanitized) - 1, -1, -1):
        digit = int(sanitized[i])

        if should_double:
            digit *= 2
            if digit > 9:
                digit -= 9

        total_sum += digit
        should_double = not should_double

    # 3. 총합이 10으로 나누어 떨어지면 유효
    return total_sum % 10 == 0

