JavaScript로 작성되었으며, 입력값의 형식(하이픈 포함 여부)에 유연하게 대응하도록 만들었습니다.

### 1. 함수 코드

```javascript
/**
 * 카드번호/계좌번호 뒤 4자리를 제외하고 마스킹하는 함수
 * @param {string} str - 마스킹할 번호 (예: "5356-5958-0835-2189" 또는 "5356595808352189")
 * @returns {string} - 마스킹된 번호 (예: "****-****-****-2189")
 */
function maskLastFourDigits(str) {
    if (!str) return '';

    // 1. 공백 제거
    const cleaned = str.trim();

    // 2. 하이픈(-)이 포함된 형식인지 확인
    const hasHyphen = cleaned.includes('-');

    // 3. 하이픈을 제거한 순수 숫자만 추출
    const numbersOnly = cleaned.replace(/-/g, '');

    // 숫자가 4자리보다 짧을 경우 예외 처리
    if (numbersOnly.length <= 4) {
        return numbersOnly;
    }

    // 4. 뒤에서 4자리와 앞의 나머지 부분 분리
    const visiblePart = numbersOnly.slice(-4);
    const hiddenPart = numbersOnly.slice(0, -4);

    // 5. 앞부분의 숫자 개수만큼 '*'로 변환
    const maskedPart = hiddenPart.replace(/\d/g, '*');

    // 6. 원래 하이픈이 있던 형식이라면 4자리 마다 하이픈 추가 (보기 좋게 정렬)
    if (hasHyphen) {
        // 4자리씩 끊어서 하이픈으로 연결
        const combined = maskedPart + visiblePart;
        return combined.replace(/(.{4})/g, '$1-').slice(0, -1);
    } 

    // 하이픈이 없었다면 그냥 붙여서 반환
    return maskedPart + visiblePart;
}

// --- 테스트 ---
const cardNumber = "5356-5958-0835-2189";
console.log(maskLastFourDigits(cardNumber)); 
// 출력결과: ****-****-****-2189

const cardNoHyphen = "5356595808352189";
console.log(maskLastFourDigits(cardNoHyphen)); 
// 출력결과: ************2189
```

