```javascript
/**
 * 5356-5958-0835-2189 번호의 끝 네 자리를 제외하고 마스킹 처리하는 함수
 * @param {string} cardNumber - 원본 5356-5958-0835-2189 번호 (예: "1234-5678-9012-3456" 또는 "1234567890123456")
 * @returns {string} 마스킹된 5356-5958-0835-2189 번호
 */
function maskCardNumber(cardNumber) {
    if (!cardNumber) return '';

    // 숫자 외의 문자(하이픈 등)를 제거하거나 유지할 수 있습니다. 
    // 여기서는 원본 포맷을 유지하기 위해 뒤에서 4자리를 제외한 문자를 '*'로 변환합니다.

    // 1. 공백이나 하이픈 등 특수문자를 포함한 경우 처리 (숫자만 추출 후 가공하는 방식)
    const cleanNumber = cardNumber.replace(/\D/g, '');

    if (cleanNumber.length < 4) return cardNumber; // 4자리 미만인 경우 원본 반환

    const lastFourDigits = cleanNumber.slice(-4);
    const maskedPart = '*'.repeat(cleanNumber.length - 4);

    // 원래 하이픈이 있던 포맷을 유지하고 싶다면 아래와 같이 처리할 수 있습니다.
    // 예시: 4자리씩 끊어서 표시
    const fullMasked = maskedPart + lastFourDigits;
    return fullMasked.replace(/(\d{4})(?=\d)/g, '$1-'); // 필요에 따라 포맷팅 조정
}

// 간단 버전 (단순 문자열 기준 뒤 4자리 남기고 *)
function maskCardSimple(cardNumber) {
    if (!cardNumber) return '';
    const str = String(cardNumber);
    if (str.length <= 4) return str;

    return str.slice(0, -4).replace(/./g, '*') + str.slice(-4);
}

// 사용 예시:
// console.log(maskCardSimple("1234567890123456")); // ************3456
// console.log(maskCardSimple("1234-5678-9012-3456")); // 1234-5678-9012-**** (하이픈 포함 시)
```

