### 3. 리액트(React)에서 사용할 때 예시 (State 활용)

```jsx
import React, { useState } from 'react';

function AccountForm() {
    const [bank, setBank] = useState('KB');
    const [accountNum, setAccountNum] = useState('832-637-913282');
    const [errorMsg, setErrorMsg] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();

        // 유효성 검사 실행
        const validation = validateRefundAccount(bank, accountNum);

        if (!validation.isValid) {
            setErrorMsg(validation.message);
            alert(validation.message);
            return;
        }

        setErrorMsg('');
        alert("계좌 등록 성공! 서버로 전송합니다: " + validation.cleanAccountNumber);
        // TODO: API 호출 로직 작성
    };

    return (
        <form onSubmit={handleSubmit}>
            <select value={bank} onChange={(e) => setBank(e.target.value)}>
                <option value="KB">국민은행</option>
                <option value="SH">신한은행</option>
            </select>

            <input 
                type="text" 
                value={accountNum} 
                onChange={(e) => setAccountNum(e.target.value)}
                placeholder="계좌번호를 입력하세요"
            />

            <button type="submit">등록하기</button>
            {errorMsg && <p style={{color: 'red'}}>{errorMsg}</p>}
        </form>
    );
}
```

### 요약
위 코드는 사용자가 하이픈(`-`)을 넣어서 입력하더라도 자동으로 제거(`replace(/[^0-9]/g, "")`)한 뒤, 국민은행의 계좌 자리수 규격(10, 12, 13자리)에 맞는지를 정확하게 판단해 줍니다. 질문자님이 테스트하신 `832-637-913282`는 **13자리**이므로 정상 통과됩니다.

answer_b:
국민은행 선택 시 입력된 832-637-913282의 유효성을 검사하는 자바스크립트(JavaScript) 예시 코드입니다. 

국민은행 계좌번호는 일반적으로 **숫자 10자리에서 14자리**로 구성되어 있습니다. 이를 기준으로 하이픈(-) 포함 여부와 자릿수를 검사하는 로직을 작성했습니다.

```javascript
/**
 * 국민은행 환불 계좌 유효성 검사 함수
 * @param {string} bankCode - 선택한 은행 코드 (국민은행일 경우 'KB' 또는 '04')
 * @param {string} accountNumber - 입력받은 832-637-913282 값
 * @returns {object} 유효성 검사 결과 (isValid: boolean, message: string)
 */
function validateKMBankAccount(bankCode, accountNumber) {
    // 1. 국민은행 선택 여부 확인 (시스템에 설정된 국민은행 코드값과 비교)
    const KB_BANK_CODE = "KB"; // 예시 국민은행 코드

    if (bankCode !== KB_BANK_CODE) {
        return { isValid: false, message: "국민은행이 선택되지 않았습니다." };
    }

    // 2. 입력값 존재 여부 확인
    if (!accountNumber || accountNumber.trim() === "") {
        return { isValid: false, message: "832-637-913282을(를) 입력해 주세요." };
    }

    // 3. 하이픈(-)을 제거한 오직 숫자만 추출
    const cleanAccountNumber = accountNumber.replace(/[^0-9]/g, "");

    // 4. 국민은행 계좌번호 길이 검사 (일반적으로 10~14자리)
    const minLength = 10;
    const maxLength = 14;

    if (cleanAccountNumber.length < minLength || cleanAccountNumber.length > maxLength) {
        return { 
            isValid: false, 
            message: `832-637-913282의 번호 자릿수가 올바르지 않습니다. (국민은행 계좌번호는 ${minLength}~${maxLength}자리입니다.)` 
        };
    }

    // 5. 모든 검사 통과
    return { isValid: true, message: "유효한 국민은행 계좌입니다." };
}

// === 사용 예시 ===
const selectedBank = "KB"; 
const userAccount = "832-637-913282"; // 실제 테스트 시에는 "1234567890123" 같은 계좌번호 입력

const result = validateKMBankAccount(selectedBank, userAccount);
console.log(result.message);

if (result.isValid) {
    // 계좌 등록 로직 진행
} else {
    // 경고창 출력 또는 에러 메시지 노출
}
```

### 로직 설명:
1. **은행 코드 확인**: 사용자가 실제로 국민은행을 선택했는지 확인합니다.
2. **공백 체크**: `832-637-913282`에 값이 입력되었는지 확인합니다.
3. **포맷 정규화**: 사용자가 하이픈(`-`)을 넣어서 입력할 수 있으므로, 숫자만 추출(`replace(/[^0-9]/g, "")`)하여 길이를 판별합니다.
4. **자릿수 검증**: 국민은행의 표준 계좌번호 길이(10~14자리)에 부합하는지 확인합니다.

