### [예시] 미르상사 전용 바코드 스캔 처리 로직 (Java)

```java
@Service
public class BarcodeScanService {

    @Autowired
    private InventoryRepository inventoryRepository;

    /**
     * 바코드 스캔 메인 진입점
     */
    public ScanResult processBarcodeScan(String scannedBarcode, String supplierId) {

        // 1. 미르상사(예: 'MIR-001') 전용 바코드 로직 분기
        if ("MIR-001".equals(supplierId)) {
            return processMirBarcode(scannedBarcode);
        }

        // 2. 일반 협력사 표준 바코드 로직
        return processStandardBarcode(scannedBarcode);
    }

    /**
     * 미르상사 전용 커스텀 스캔 로직
     */
    private ScanResult processMirBarcode(String barcode) {
        // [커스텀 규칙 1] 미르상사는 바코드에 특정 기호가 포함되어 있거나 자릿수가 다를 수 있음
        if (!barcode.startsWith("MIR_CUSTOM_")) {
            return new ScanResult(false, "미르상사 표준 바코드 양식이 아닙니다.");
        }

        // [커스텀 규칙 2] 바코드 파싱 (예: 미르상사는 바코드에 로트번호와 유통기한이 함께 암호화되어 있는 경우)
        String itemCode = parseMirItemCode(barcode);
        int quantity = parseMirQuantity(barcode);

        // [커스텀 규칙 3] 미르상사 전용 재고 검수 프로세스 수행
        // 예: 입고 시 자동 검수 상태로 변경 등
        inventoryRepository.updateStockStatus(itemCode, quantity, "MIR_INSPECTED");

        return new ScanResult(true, "미르상사 상품 스캔 완료: " + itemCode + " (" + quantity + "개)");
    }

    private ScanResult processStandardBarcode(String barcode) {
        // 기존 표준 로직
        return new ScanResult(true, "표준 바코드 스캔 완료");
    }

    private String parseMirItemCode(String barcode) {
        // 파싱 로직 구현
        return barcode.substring(11, 20);
    }

    private int parseMirQuantity(String barcode) {
        // 수량 파싱 로직 구현
        return 1; 
    }
}
