### 2. 구현 코드 예시 (JavaScript/Node.js 기준)

```javascript
/**
 * 바코드 스캔 처리 메인 함수
 * @param {string} rawBarcode - 스캔된 원본 바코드 문자열
 * @param {string} clientId - 현재 작업 중인 고객사 ID
 */
function processBarcodeScan(rawBarcode, clientId) {
    // 1. 공통 바코드 처리 로직
    if (!rawBarcode) {
        return { success: false, message: "바코드가 입력되지 않았습니다." };
    }

    // 2. 고객사별 분기 처리
    if (clientId === "미르상사") {
        return handleCustomBarcodeForClient1(rawBarcode);
    } else {
        return handleStandardBarcode(rawBarcode);
    }
}

/**
 * 미르상사 전용 바코드 스캔 커스텀 로직
 */
function handleCustomBarcodeForClient1(barcode) {
    const PREFIX = "CUST1-";
    const EXPECTED_LENGTH = 12;

    // 규칙 1: 접두사 확인
    if (!barcode.startsWith(PREFIX)) {
        return { 
            success: false, 
            message: "미르상사 전용 바코드가 아닙니다. (접두사 오류)" 
        };
    }

    // 규칙 2: 길이 확인
    if (barcode.length !== EXPECTED_LENGTH) {
        return { 
            success: false, 
            message: `미르상사 바코드 규격 오류. (필요 길이: ${EXPECTED_LENGTH}, 실제: ${barcode.length})` 
        };
    }

    // 규칙 3: 데이터 파싱 (예: 접두사 제거 후 상품코드 추출)
    const productCode = barcode.replace(PREFIX, "");

    // 미르상사 전용 추가 비즈니스 로직 수행 가능
    console.log(`미르상사 물류 시스템 연동 완료: 상품코드 ${productCode}`);

    return {
        success: true,
        client: "미르상사",
        data: {
            productCode: productCode,
            scannedAt: new Date().toISOString()
        },
        message: "미르상사 바코드 스캔 및 검증 성공"
    };
}

/**
 * 표준 바코드 처리 로직 (기타 고객사용)
 */
function handleStandardBarcode(barcode) {
    // 기존 표준 WMS 바코드 로직
    return {
        success: true,
        client: "STANDARD",
        data: { barcode },
        message: "표준 바코드 스캔 성공"
    };
}

// 모듈 내보내기
module.exports = { processBarcodeScan };
```

